    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      suffix := suffix + [next];
      if next == ">>" {
        insideConstrainedOut := false;
        currentConstrainedOut := [];
      } else {
        currentConstrainedOut := currentConstrainedOut + [next];
      }
    }
  }
}

cost := steps;
